    // 校验执行周期
  if(!V8.Form.ZhiXingZQ){
    V8.Tips("请选择执行周期", false);
    V8.Result = false;
    return;
  }
  // 依据执行周期生成cron表达式
  if(V8.Form.ZhiXingZQ == "每天"){
    if(!V8.Form.XiaoShi && String(V8.Form.XiaoShi) !== '0'){
      V8.Tips("请输入小时", false);
      V8.Result = false;
      return;
    } 
    if(!V8.Form.FenZhong && String(V8.Form.FenZhong) !== '0'){
      V8.Tips("请输入分钟", false);
      V8.Result = false;
      return;
    } 
